2257:
SELECT ?year ?givenName ?givenNameLabel ?count WHERE {
  {
    SELECT ?year (MAX(?count) AS ?maxCount) WHERE {
      ?givenName wdt:[property:instance of] wd:[entity:female given name] .
      ?givenName p:[property:number of records] ?statement .
      ?statement ps:[property:number of records] ?count .
      ?statement pq:[property:point in time] ?date .
      ?statement pq:[property:country] wd:[entity:Germany] .
      BIND(YEAR(?date) AS ?year)
    }
    GROUP BY ?year
  }
  ?givenName p:[property:number of records] ?statement .
  ?statement ps:[property:number of records] ?count .
  ?statement pq:[property:point in time] ?date .
  ?statement pq:[property:country] wd:[entity:Germany] .
  BIND(YEAR(?date) AS ?year)
  FILTER(?count = ?maxCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?year

