  ?character wdt:[property:instance of] wd:[entity:fictional character] .
  ?character wdt:[property:family name] ?familyName .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?familyName ?familyNameLabel
ORDER BY DESC(?count)
LIMIT 50

1459:
SELECT ?district ?districtLabel ?geoshape ?votePercentage ?rgb WHERE {
  ?result wdt:[property:instance of] wd:[entity:electoral result] ;
          wdt:[property:point in time] ?date ;
          wdt:[property:electoral district] ?district .
  FILTER(YEAR(?date) = 2017)
  ?district wdt:[property:geoshape] ?geoshape .
  ?result wdt:[property:proportion] ?votePercentage .
  BIND(
    IF(?votePercentage < 0.2, "#FF0000",
    IF(?votePercentage < 0.4, "#FFA500",
    IF(?votePercentage < 0.6, "#FFFF00", "#00FF00"))) AS ?rgb)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

